<script setup lang="ts">
import {computed,ref,watch,nextTick} from 'vue'
import {RouterLink} from 'vue-router'
import type {Trip,TripDay,ItineraryItem,Memory,JournalEntry} from '@/types'
import {orderedActivities,overlapping,dayLabel,outsideRange,timeLabel,directions,activityDuration} from '@/composables/tripPlanner'
const props=defineProps<{trip:Trip;days:TripDay[];items:ItineraryItem[];activeDay:string;view:'timeline'|'overview';busy:boolean;mode?:'itinerary'|'ideas'|'today';memories:Memory[];journals:JournalEntry[]}>()
const emit=defineEmits<{'update:activeDay':[string];'update:view':['timeline'|'overview'];add:[string];edit:[ItineraryItem];options:[ItineraryItem];plan:[ItineraryItem];addDay:[];nameDay:[TripDay];reorder:[string,string,string]}>()
const normalDays=computed(()=>props.days.filter(d=>!d.is_ideas).sort((a,b)=>a.day_number-b.day_number))
const day=computed(()=>props.days.find(d=>d.id===props.activeDay))
const rows=(id:string)=>orderedActivities(props.items.filter(i=>i.trip_day_id===id))
const timed=computed(()=>day.value?rows(day.value.id).filter(i=>i.scheduled_time):[])
const flexible=computed(()=>day.value?rows(day.value.id).filter(i=>!i.scheduled_time):[])
const conflicts=computed(()=>overlapping(props.items,props.days))
const overview=computed(()=>props.mode==='itinerary'&&props.view==='overview')
const subtitle=(d:TripDay)=>d.title&&d.title!=='Day '+d.day_number?d.title:''
const date=(d:TripDay)=>d.date?new Date(d.date+'T12:00:00').toLocaleDateString('en',{weekday:'short',month:'short',day:'numeric'}):'Date to come'
const dayTabs=ref<HTMLElement|null>(null)
watch(()=>props.activeDay,async()=>{await nextTick();const el=dayTabs.value?.querySelector<HTMLElement>('[aria-selected=true]');if(el&&dayTabs.value){const left=el.offsetLeft-dayTabs.value.offsetLeft;dayTabs.value.scrollTo({left:Math.max(0,left-dayTabs.value.clientWidth/2+el.clientWidth/2),behavior:'instant'})}})
function tabKey(e:KeyboardEvent,index:number){let target=index;if(e.key==='ArrowRight')target=Math.min(normalDays.value.length-1,index+1);else if(e.key==='ArrowLeft')target=Math.max(0,index-1);else if(e.key==='Home')target=0;else if(e.key==='End')target=normalDays.value.length-1;else return;e.preventDefault();emit('update:activeDay',normalDays.value[target].id);nextTick(()=>dayTabs.value?.querySelector<HTMLElement>('[aria-selected=true]')?.focus({preventScroll:true}))}
const dragging=ref(''),drop=ref(''),board=ref<HTMLElement|null>(null)
function start(e:PointerEvent,item:ItineraryItem){if(props.busy||e.button!==0)return;e.preventDefault();(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);dragging.value=item.id;drop.value=item.id}
function move(e:PointerEvent){if(!dragging.value)return;const found=[...board.value!.querySelectorAll<HTMLElement>('[data-flexible-id]')].find(el=>{const r=el.getBoundingClientRect();return e.clientY>=r.top&&e.clientY<=r.bottom});if(found)drop.value=found.dataset.flexibleId!}
function finish(){if(dragging.value&&drop.value&&dragging.value!==drop.value&&day.value)emit('reorder',day.value.id,dragging.value,drop.value);dragging.value='';drop.value=''}
</script>
<template><section ref="board" class="itinerary-board" :class="{overview,'ideas-mode':mode==='ideas'}">
 <div v-if="mode==='itinerary'" class="view-controls"><div class="view-switch" role="group" aria-label="Itinerary view"><button :aria-pressed="view==='timeline'" @click="emit('update:view','timeline')">Daily timeline</button><button :aria-pressed="view==='overview'" @click="emit('update:view','overview')">Trip overview</button></div><details class="order-help"><summary aria-label="How ordering works">?</summary><p>Timed activities follow the clock, with manual order breaking ties. Flexible activities keep your chosen order. Change a time to reschedule; use the arrows or drag handle to reorder flexible plans.</p></details></div>
 <template v-if="mode==='itinerary'&&!overview"><div class="day-navigation"><div ref="dayTabs" class="day-tabs" role="tablist" aria-label="Itinerary days"><button v-for="(d,index) in normalDays" :key="d.id" role="tab" :aria-selected="activeDay===d.id" :tabindex="activeDay===d.id?0:-1" :aria-label="dayLabel(d)+' · '+date(d)" @click="emit('update:activeDay',d.id)" @keydown="tabKey($event,index)"><strong>{{dayLabel(d)}}</strong><span>{{date(d)}}</span></button></div><button class="add-day" :disabled="busy" @click="emit('addDay')">＋ Day</button></div><label v-if="normalDays.length>7" class="day-jump"><span class="sr-only">Jump to day</span><select :value="activeDay" @change="emit('update:activeDay',($event.target as HTMLSelectElement).value)"><option v-for="d in normalDays" :key="d.id" :value="d.id">{{dayLabel(d)}} · {{date(d)}} {{subtitle(d)}}</option></select></label></template>
 <div v-if="overview" class="overview-days"><section v-for="d in normalDays" :key="d.id" class="overview-day"><header><div class="day-number" aria-hidden="true">{{String(d.day_number).padStart(2,'0')}}</div><div><p class="eyebrow">{{dayLabel(d)}} · {{date(d)}}</p><h2>{{subtitle(d)||'An open day'}}</h2><p v-if="outsideRange(d,trip)" class="outside-label">Outside current travel dates · kept in your plan</p></div><button :aria-label="'Name '+dayLabel(d)" @click="emit('nameDay',d)" :disabled="busy">Name day</button></header><div class="overview-labels" aria-hidden="true"><span>Time</span><span>Activity</span><span>Place</span></div><button v-for="item in rows(d.id)" :key="item.id" class="overview-row" :aria-label="'Edit '+item.title" :disabled="busy" @click="emit('edit',item)"><span class="row-time">{{timeLabel(item)}}<small v-if="!item.scheduled_time">Flexible</small></span><span class="row-title">{{item.title}}<small v-if="item.description">{{item.description}}</small><small v-if="conflicts.has(item.id)" class="overlap">Times overlap</small></span><span class="row-place">{{item.location_name||item.location?.name||'Place to come'}}</span></button><p v-if="!rows(d.id).length" class="overview-empty">A little room for discovery.</p><button class="overview-add" :disabled="busy" :aria-label="'Add activity to '+dayLabel(d)" @click="emit('add',d.id)">＋ Add activity</button><button class="open-day" @click="emit('update:activeDay',d.id);emit('update:view','timeline')">Open {{dayLabel(d)}} →</button></section><button :disabled="busy" @click="emit('addDay')">＋ Add another day</button></div>
 <template v-else-if="day"><header class="day-heading"><div><p class="eyebrow">{{day.is_ideas?'Unscheduled possibilities':dayLabel(day)+' · '+date(day)}}</p><h2>{{day.is_ideas?'A few lovely possibilities.':subtitle(day)||'A day to make your own.'}}</h2></div><button v-if="!day.is_ideas" :aria-label="'Name '+dayLabel(day)" @click="emit('nameDay',day)" :disabled="busy">Name day</button></header><p v-if="outsideRange(day,trip)" class="notice">This day is outside your current travel dates. Every activity is kept. Move items to another day or revise the dates.</p><p v-if="day.is_ideas" class="muted ideas-intro">Collect places, meals and little reminders. Choose Plan this when one finds its day.</p>
 <template v-for="group in [{id:'timed',label:'On the clock',items:timed},{id:'flexible',label:day.is_ideas?'Ideas':'Flexible · any time',items:flexible}]" :key="group.id"><section v-if="group.items.length" class="timeline-group" :class="group.id"><h3 class="group-label">{{group.label}}</h3><div class="activities"><article v-for="(item,index) in group.items" :key="item.id" class="activity-card" :class="{completed:item.status==='visited','drop-target':dragging&&drop===item.id}" :data-activity-id="item.id" :data-flexible-id="group.id==='flexible'?item.id:undefined"><div v-if="group.id==='timed'" class="time-rail"><time>{{item.scheduled_time?.slice(0,5)}}</time><span v-if="item.end_time">{{item.end_time.slice(0,5)}}<small v-if="item.end_day_offset">+1 day</small></span><i aria-hidden="true"></i></div><div class="event-paper" :data-category="item.item_type||item.category||'activity'"><div class="event-meta"><span>{{({transport:'Transport',meal:'Food & drink',lodging:'Stay',activity:'Explore',other:'Personal'} as Record<string,string>)[item.item_type||item.category||'activity']||'Explore'}}</span><span v-if="activityDuration(item)">{{activityDuration(item)}} min</span><span v-if="item.status!=='planned'">{{item.status==='visited'?'Completed':item.status}}</span><span v-if="!item.scheduled_time">{{item.time_label||'Flexible'}}</span></div><h3><button class="event-title" title="Edit activity" @click="emit('edit',item)" :disabled="busy">{{item.title}}</button></h3><p v-if="item.location_name||item.location?.name" class="event-place">⌖ {{item.location_name||item.location?.name}}</p><p v-if="item.description" class="event-notes">{{item.description}}</p><p v-if="item.booking_reference" class="booking">Reference · {{item.booking_reference}}</p><p v-if="conflicts.has(item.id)" class="overlap">Times overlap. Keep the plan or adjust in Edit.</p><div class="activity-links"><a v-if="directions(item)" :href="directions(item)!" target="_blank" rel="noopener noreferrer">Directions ↗</a><RouterLink v-for="m in memories.filter(m=>m.itinerary_item_id===item.id)" :key="m.id" :to="'/memories/'+m.id">{{m.title}} ↗</RouterLink><RouterLink v-for="j in journals.filter(j=>j.itinerary_item_id===item.id)" :key="j.id" :to="'/journal/'+j.id">{{j.title}} ↗</RouterLink></div><div class="activity-actions"><button v-if="day.is_ideas" class="plan-idea" :disabled="busy" @click="emit('plan',item)">Plan this</button><button :aria-label="'Edit '+item.title" @click="emit('edit',item)" :disabled="busy">Edit</button><button :aria-label="'Options for '+item.title" @click="emit('options',item)" :disabled="busy">More</button><template v-if="group.id==='flexible'"><button :aria-label="'Move '+item.title+' up'" :disabled="busy||index===0" @click="emit('reorder',day.id,item.id,group.items[index-1].id)">↑</button><button :aria-label="'Move '+item.title+' down'" :disabled="busy||index===group.items.length-1" @click="emit('reorder',day.id,item.id,group.items[index+1].id)">↓</button><button class="drag-handle" :aria-label="'Drag '+item.title+' to reorder'" :disabled="busy" @pointerdown="start($event,item)" @pointermove="move" @pointerup="finish" @pointercancel="dragging='';drop=''">⠿</button></template></div></div></article></div></section></template>
 <section v-if="!timed.length&&!flexible.length" class="day-empty"><span aria-hidden="true">⌁</span><h3>A place, a meal, an unhurried afternoon.</h3><p>Start with one thing you’d like to do. Times can come later.</p></section>
 <div class="day-add"><button class="primary" :disabled="busy" @click="emit('add',day.id)">＋ {{day.is_ideas?'Add idea':'Add activity'}}</button><span>{{timed.length+flexible.length}} {{timed.length+flexible.length===1?'activity':'activities'}} · room for more</span></div>
 </template><section v-else class="empty"><h2>No day scheduled for today.</h2><p>Your other days are kept in the itinerary.</p></section>
</section></template>
<style scoped>
.itinerary-board{min-width:0}.view-controls{display:grid;grid-template-columns:minmax(0,1fr) 44px;gap:10px;align-items:center;margin-bottom:14px}.view-switch{display:flex;justify-self:start;padding:4px;background:#e6e7db;border-radius:9px}.view-switch button{border:0;background:transparent;padding:8px 12px}.view-switch button[aria-pressed=true]{background:#fffaf1;color:#74283c;box-shadow:0 2px 6px #49352112}.order-help{position:relative;font-size:13px;color:#756b5c}.order-help summary{font:18px Georgia;justify-content:center;border:1px solid #d8ccb8;border-radius:50%;width:44px;height:44px;margin:0!important}.order-help p{position:absolute;right:0;top:52px;width:min(310px,80vw);line-height:1.6;padding:18px;border:1px solid #d8ccb8;border-radius:10px;background:#fffbf2;box-shadow:0 8px 24px #49352125;z-index:6}.day-navigation{display:flex;gap:10px;align-items:stretch;min-width:0}.day-tabs{display:flex;gap:8px;overflow-x:auto;scrollbar-width:thin;padding:5px 5px 10px;flex:1;min-width:0}.day-tabs button{flex-shrink:0;min-width:112px;display:flex;flex-direction:column;gap:4px;align-items:flex-start;padding:10px 14px;background:#f7f2e7}.day-tabs strong{font-weight:600}.day-tabs span{font-size:12px;color:#7c725f}.day-tabs [aria-selected=true]{background:#74283c;border-color:#74283c;color:#fff7e8}.day-tabs [aria-selected=true] span{color:#efdfd3}.add-day{align-self:flex-start;min-height:66px!important}.day-jump{max-width:360px;margin:4px 0 8px}.day-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:22px 0 18px}.day-heading h2{font-size:31px;margin:6px 0 0}.day-heading>button{flex-shrink:0}.group-label{font:11px Inter,sans-serif!important;letter-spacing:.12em;text-transform:uppercase;color:#7c8069;margin:12px 0 18px}.activities{display:grid;gap:16px}.activity-card{position:relative;min-width:0}.timed .activity-card{display:grid;grid-template-columns:64px minmax(0,1fr);gap:16px}.time-rail{position:relative;text-align:right;padding:22px 16px 0 0;color:#74283c;font-variant-numeric:tabular-nums}.time-rail:after{content:'';position:absolute;top:0;bottom:-16px;right:-7px;width:1px;background:#cec5b2}.activity-card:last-child .time-rail:after{bottom:25px}.time-rail i{position:absolute;width:9px;height:9px;right:-11px;top:29px;border:2px solid #8b9776;border-radius:50%;background:#f4eadc;z-index:1}.time-rail time{font-size:17px;font-weight:600;display:block}.time-rail>span{font-size:12px;display:block;margin-top:6px;color:#7f7563}.time-rail small{display:block}.event-paper{background:#fffbf3;border:1px solid #ddd1bd;border-radius:9px;padding:20px;box-shadow:0 4px 14px #634a2a08;min-width:0}.event-meta{display:flex;flex-wrap:wrap;gap:10px;font-size:10px;text-transform:uppercase;letter-spacing:.08em;color:#788365}.event-title{font:26px/1.15 'Crimson Text',Georgia,serif!important;text-align:left!important;justify-content:flex-start!important;display:block!important;border:0!important;padding:4px 0!important;background:none!important;color:#51483e!important;width:100%;overflow-wrap:anywhere}.event-paper h3{margin:6px 0}.event-place{font-size:14px;color:#667356;margin:8px 0;overflow-wrap:anywhere}.event-notes{font-size:14px;line-height:1.7;color:#776a58;white-space:pre-wrap;overflow-wrap:anywhere}.booking{font:12px/1.6 monospace;margin-top:10px;overflow-wrap:anywhere}.activity-links{display:flex;flex-wrap:wrap;gap:12px}.activity-links a{font-size:13px;min-height:44px;display:inline-flex;align-items:center;color:#74283c}.activity-actions{display:flex;gap:4px;margin-top:12px;flex-wrap:wrap}.activity-actions button{padding:8px 10px}.flexible .activity-actions{display:grid;grid-template-columns:repeat(5,minmax(44px,1fr));max-width:310px}.activity-actions .drag-handle{touch-action:none;cursor:grab;font-size:22px}.flexible{margin-top:28px}.flexible .event-paper{border-left:3px solid #9aa487}.drop-target{outline:3px solid #8a9573;outline-offset:3px;border-radius:9px}.completed .event-meta{color:#52704f}.overlap{font-size:12px;color:#8a5b30;margin:12px 0 0}.day-add{position:sticky;bottom:0;display:flex;align-items:center;gap:14px;padding:14px 0 max(14px,env(safe-area-inset-bottom));margin-top:18px;background:#f5ecdd;z-index:3;border-top:1px solid #dfd3bf}.day-add span{font:18px 'Caveat',cursive;color:#768064}.day-empty{padding:30px 20px;text-align:center;background:#f9f4e9;border:1px dashed #d8ccb8;border-radius:10px}.day-empty>span{font:48px Georgia;color:#8b9776}.day-empty h3{font-size:25px;margin:10px 0}.day-empty p{font-size:14px;color:#81725f;line-height:1.6}.overview-days{display:grid;gap:24px}.overview-day{background:#fffbf2;border:1px solid #daceb8;border-radius:10px;overflow:hidden}.overview-day>header{display:flex;align-items:center;gap:16px;padding:22px;background:#e6e8dc}.overview-day header>div:nth-child(2){flex:1;min-width:0}.overview-day h2{font-size:27px;margin:5px 0 0}.day-number{font:italic 40px Georgia;color:#8a9675}.overview-day header>button{flex-shrink:0}.overview-labels{display:grid;grid-template-columns:150px minmax(0,1fr) minmax(120px,.6fr);padding:14px 22px;gap:18px;font-size:10px;text-transform:uppercase;letter-spacing:.12em;color:#7c816d;border-bottom:1px solid #e4d9c6}.overview-row{display:grid!important;grid-template-columns:150px minmax(0,1fr) minmax(120px,.6fr);gap:18px!important;width:100%;text-align:left!important;align-items:start!important;justify-content:initial!important;padding:20px 22px!important;border:0!important;border-bottom:1px solid #e4d9c6!important;border-radius:0!important;background:transparent!important;color:#55483d!important}.row-time{font-size:13px;font-variant-numeric:tabular-nums;color:#74283c}.row-title{font:24px/1.25 'Crimson Text',Georgia,serif;overflow-wrap:anywhere}.overview-row small{display:block;font:13px/1.6 Inter,sans-serif;color:#82745f;margin-top:6px;white-space:pre-wrap}.row-place{font-size:14px;line-height:1.6;color:#69745c;overflow-wrap:anywhere}.overview-add,.open-day{margin:12px!important;border:0!important;background:transparent!important}.open-day{float:right}.overview-empty{padding:22px;font:21px 'Caveat',cursive;color:#7a846c}.outside-label{font-size:12px;line-height:1.5;color:#8a643d;margin-top:8px}
@media(max-width:699px){.view-controls{gap:8px}.view-switch{width:100%}.view-switch button{flex:1}.order-help{width:44px}.day-heading{align-items:flex-start;gap:10px}.day-heading h2{font-size:27px}.day-heading>button{padding:8px;font-size:12px}.timed .activity-card{grid-template-columns:48px minmax(0,1fr);gap:12px}.time-rail{padding-right:6px}.time-rail time{font-size:15px}.time-rail:after{right:-6px}.time-rail i{right:-10px}.event-paper{padding:16px 14px}.event-title{font-size:24px!important}.overview-day>header{padding:16px;gap:10px}.day-number{font-size:32px}.overview-day h2{font-size:25px}.overview-day header>button{font-size:12px;padding:8px}.overview-labels{display:none}.overview-row{grid-template-columns:minmax(0,1fr);gap:8px!important;padding:18px!important}.row-time{font-weight:600}.row-time small{display:inline;margin-left:8px}.row-place:before{content:'⌖ ';color:#879476}.overview-add,.open-day{margin:8px!important;font-size:13px}.day-add span{font-size:16px}}
</style>
